#include <cstdint>
#include <iostream>
#include <map>
#include <vector>

enum class PageState { free, reserved, committed };

class AddressSpace
{
public:
    bool reserve(std::uint64_t base, std::uint64_t size) { return false; }
    bool commit(std::uint64_t address, std::uint64_t size) { return false; }
    bool canWrite(std::uint64_t address) const { return false; }

private:
    std::map<std::uint64_t, PageState> m_pages{};
};

int main()
{
    AddressSpace a{};
    a.reserve(0x10000000, 1 << 20);
}
